        type: 'INTUITION',
        title: 'Salary vs Selling Your Gold: The Revenue Receipt Test',
        body: 'Consider your personal household finances. When you receive your monthly salary of ₹80,000, that is "pure income":\n1. You do not have to repay it to anyone (no liability created).\n2. You did not have to sell your ancestral land or gold to get it (no asset reduced).\n\nNow suppose you take a personal bank loan of ₹5,00,000 or sell a gold chain for ₹50,000. Cash comes into your bank account, but it is NOT revenue income! The loan creates a liability you must repay with interest, and selling the gold reduces your physical assets.\n\nIn public economics, the government applies this exact same logic. Inflows that create zero debt and sell zero assets are **Revenue Receipts**. Inflows that create debt or liquidate assets are **Capital Receipts**.',
        order: 1,
