        type: 'EXAM_APPLICATION',
        title: 'Exam Traps & Multi-Exam Crosswalks',
        body: '### Critical Examiner Traps\n- **Trap 1: External Grants vs External Loans**:\n  - **External Cash Grants** (non-repayable gift from foreign governments or multilateral agencies) = **Revenue Receipt**.\n  - **External Loans** (repayable borrowings from World Bank / ADB) = **Capital Receipt**.\n- **Trap 2: RBI Surplus Transfer Accounting**: RBI surplus is NOT a tax, nor a loan. It is accounted under **Non-Tax Revenue $\\to$ Dividends and Profits**.\n- **Trap 3: Recovery of Loans**: When the Centre recovers a loan given to a State government, it is NOT revenue! Loan recovery is a **Non-Debt Capital Receipt** because it reduces the Centre\'s financial assets.\n- **Trap 4: Cesses and Surcharges**: Cesses (e.g., Health & Education Cess) and Surcharges on taxes are part of Gross Tax Revenue, but are **NOT shared with States** in the divisible pool under Article 270.\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: Gross vs Net Tax Revenue formulas, RBI dividend accounting, and Cesses/Surcharges sharing rules.\n- **SBI/IBPS PO & RPSC RAS**: Classifying items as Tax vs Non-Tax Revenue, and identifying grants vs loans.',
