        body: '### 1. Types of Disinvestment\n- **Minority Disinvestment**: The government sells a small portion of equity (e.g., $5\\%-10\\%$) via Offer for Sale (OFS) or IPO while retaining at least **$51\\%$ shareholding and management control**.\n- **Strategic Disinvestment**: The government sells **$50\\%$ or more of equity** along with the transfer of management control to a strategic private buyer (e.g., privatization of Air India).\n- **Asset Monetization**: Leasing core infrastructure assets (toll roads, transmission lines, railway stations) for long-term concessions under the **National Monetization Pipeline (NMP)** without transferring underlying land ownership.\n\n### 2. The Golden Accounting Identity\n$$\\text{Total Receipts} = \\text{Revenue Receipts} + \\text{Non-Debt Capital Receipts} + \\text{Debt Capital Receipts}$$\n$$\\text{Total Expenditure} - (\\text{Revenue Receipts} + \\text{NDCR}) = \\text{Fiscal Deficit} = \\text{Debt Capital Receipts}$$',
