        title: 'Exam Traps & Multi-Exam Crosswalks',
        body: '### Critical Examiner Traps\n- **Trap 1: Interest vs Principal on Loans**:\n  - **Interest received** on loans given to States = **Revenue Receipt (Non-Tax)** (no asset reduced, no liability created).\n  - **Recovery of Principal** of loans given to States = **Non-Debt Capital Receipt** (reduces financial asset / loan book).\n- **Trap 2: Disinvestment as Revenue**: Disinvestment proceeds are **Capital Receipts (Non-Debt)**, NOT revenue receipts, because selling equity liquidates government assets.\n- **Trap 3: Small Savings (NSSF)**: Public deposits in Post Office Savings and PPF flow into the **Public Account**, from which the Centre borrows via special securities; this is a **Debt Capital Receipt**.\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: NDCR vs DCR classification, Fiscal Deficit financing identity, and National Small Savings Fund (NSSF) accounting.\n- **SBI/IBPS PO & RPSC RAS**: Distinguishing interest received (Revenue) from principal recovered (Capital), and identifying disinvestment as NDCR.',
