        type: 'FLASH_30S',
        content: 'Tax Structures: Progressive ($MTR > ATR$, e.g., Income Tax), Proportional ($MTR = ATR$, Flat), Regressive ($MTR < ATR$, e.g., Sales Tax). Equity: Horizontal (equals treated equally), Vertical (unequals treated unequally). Adam Smith\'s 4 Canons: Equality, Certainty, Convenience, Economy. Tax Buoyancy = $(\\%\\Delta T)/(\\%\\Delta GDP)$ (includes policy changes). Tax Elasticity = automatic responsiveness (excludes policy changes).',
