        type: 'INTUITION',
        title: 'Why Was GST Necessary? The Death of "Tax-on-Tax"',
        body: 'Before July 1, 2017, the Indian indirect tax landscape was a chaotic nightmare of 17 separate central and state taxes (Central Excise, Service Tax, State VAT, CST, Entry Tax, Octroi, Luxury Tax).\n\nSuppose a factory manufactured a leather bag for ₹1,000:\n1. The Centre levied a $12.5\\%$ Central Excise Duty = ₹125 (Price = ₹1,125).\n2. When the bag was shipped to a retailer, the State levied a $14.5\\%$ State VAT on the **entire ₹1,125**! This meant the state was charging VAT on top of the Central Excise Duty (**Tax on a Tax = Cascading**).\n3. When the truck crossed the state border, it waited 3 days in a traffic jam to pay Entry Tax and Octroi.\n\n**GST destroyed this entire mess**. It created "One Nation, One Tax, One Market", eliminated state border checkpoints, and allowed every business to deduct input taxes paid at earlier stages, so tax is paid **ONLY on the fresh value added**.',
