        content: 'The Goods and Services Tax (GST), launched on July 1, 2017 via the 101st Constitutional Amendment Act, replaced 17 central and state indirect taxes with a unified, destination-based consumption tax. Under the destination principle, tax revenue accrues to the state where goods/services are ultimately consumed rather than where they are produced. The Input Tax Credit (ITC) mechanism ensures that tax is paid strictly on the value added at each stage of the supply chain by allowing businesses to deduct taxes paid on inputs from their output tax liability, eliminating the cascading "tax-on-tax" distortion. Key exclusions include alcoholic liquor for human consumption (permanently excluded by Article 366(12A)) and five petroleum products (temporarily kept outside GST under Section 9(2)).',
