        body: 'In most federal nations (like Canada or Brazil), indirect tax reforms caused bitter political fights where central governments bullied states or states rebelled.\n\nIndia solved this with a constitutional masterpiece: **The GST Council (Article 279A)**.\n\nNeither the Centre nor the States can dictate terms alone:\n- The Centre has **$33.33\\%$ of the voting power**, meaning it has a veto over any state-led resolution (since $75\\%$ is needed to pass).\n- But all 28 States combined have **$66.67\\%$ of the voting power**, meaning the Centre cannot pass any tax hike unless at least **20 States agree with it**!\n\nThis forces constant cooperative federalism: every tax rate, exemption, and rule must be negotiated through consensus.',
