        title: 'Buying Groceries vs Buying a Tractor: The Expenditure Test',
        body: 'Consider a farming household:\n- If the farmer spends ₹20,000 on monthly groceries, electricity bills, and medicine, that is **Revenue Expenditure**. It is consumed immediately to keep the family alive and healthy, but leaves behind no tangible machine or debt reduction.\n- If the farmer spends ₹5,00,000 to purchase a modern tractor or pay off an old mortgage, that is **Capital Expenditure**. The tractor will increase crop output for the next 15 years, and repaying the mortgage eliminates debt.\n\nGovernments function similarly:\n- Paying salaries to police officers, paying interest on national debt, and providing food subsidies = **Revenue Expenditure**.\n- Building the Delhi-Mumbai Expressway, laying high-speed railway tracks, and building AIIMS hospitals = **Capital Expenditure (CapEx)**.',
