        body: 'In popular media, Revenue Expenditure is often wrongly labeled as "wasteful consumption" and Capital Expenditure as "virtuous investment". This is an economic fallacy!\n\n### The Economic Nuance\n1. **Human Capital is Built by Revenue Spending**: Paying the salary of an exceptional scientist at ISRO, a surgeon at AIIMS, or a primary school teacher is accounted as *Revenue Expenditure*. Yet, it generates immense long-term economic productivity and human capital!\n2. **Maintenance Prevents Capital Destruction**: Spending revenue money to repair potholes and maintain railway signals prevents multi-crore infrastructure assets from degrading.\n3. **White Elephant CapEx**: Spending ₹10,000 Crore of capital expenditure to build a 6-lane highway through an uninhabited desert generates zero economic return and destroys public wealth.\n\n*Key Lesson*: What matters in macroeconomics is the **quality, efficiency, and social multiplier of the spending**, not its formal accounting label!',
