        title: 'The Three Government Safes: Who Holds the Key?',
        body: 'Imagine the Government of India manages three distinct bank accounts:\n\n1. **The Sovereign Master Safe (Consolidated Fund of India - Art 266(1))**: Contains all taxes you pay, all government bond borrowings, and all loan recoveries. The key to this safe is held exclusively by **Parliament**! Not even the Prime Minister can take out one single rupee without a formal Appropriation Law passed by elected MPs.\n\n2. **The Emergency Petty Cash (Contingency Fund - Art 267)**: Kept for unexpected crises (earthquakes, war, sudden pandemics). The key is held by the **President of India** (operated by the Finance Secretary) to release immediate relief funds without waiting months for Parliament to meet.\n\n3. **The Public Trustee Vault (Public Account - Art 266(2))**: Holds money that does not belong to the government (your Post Office Small Savings, Provident Fund / GPF, court deposits). The government acts merely as a trustee/banker; executive officers can withdraw and disburse this money without parliamentary voting.',
