        body: 'Suppose a country\'s fiscal deficit increases from ₹10 Lakh Crore to ₹15 Lakh Crore this year.\n\nDid the government become reckless, or did something else happen?\n\n- **Scenario A (Cyclical Deficit)**: A sudden global recession hit, causing factory profits to plunge by $30\\%$ (tax revenues collapsed) and millions of people to register for MGNREGA unemployment work (spending surged). The deficit increased **automatically because the economy shrank**, not because politicians passed new wasteful budgets.\n\n- **Scenario B (Structural Deficit)**: The economy is booming at full employment, but the government passes permanent populist pre-election subsidies costing ₹5 Lakh Crore. This is a **Structural Deficit**—a permanent deficit built into the legal tax and spending code that will NOT disappear even when the boom continues!\n\nEconomists separate these two to evaluate whether a budget is fundamentally broken or just weathering a temporary storm.',
