        body: 'Think of the national economy as a large house:\n\n- **In Winter (Economic Recession)**: Consumer spending drops, factories lay off workers, and total spending is freezing cold. The government acts as a **heater (Expansionary Fiscal Policy)**: it turns up government spending on roads, hires workers, and cuts income taxes so households have more cash to spend.\n\n- **In Summer (Overheating & Inflation)**: Demand is roaring, prices are spiking by $10\\%$ a year, and the economy is boiling over. The government acts as an **air conditioner (Contractionary Fiscal Policy)**: it delays non-urgent projects, cuts subsidies, and raises taxes to cool down aggregate demand.\n\nFurthermore, modern economies have built-in **smart thermostats (Automatic Stabilizers)**: when your income drops during a recession, the tax system automatically drops you into a lower tax slab, instantly saving you cash without Parliament needing to pass a new law!',
