        body: 'Why are automatic stabilizers superior to discretionary policy for minor economic shocks?\n\n1. **Zero Legislative Lag**: They react in real-time on day one without waiting for parliamentary budget sessions.\n2. **The Progressive Tax Channel**: In a boom, as wages rise, workers automatically move into higher tax brackets ($10\\% \\to 20\\% \\to 30\\%$), draining excess purchasing power and cooling inflation (**Fiscal Drag**). In a recession, incomes drop, automatically reducing tax bills.\n3. **The Social Safety Net Channel (MGNREGA in India)**:\n   - Under the Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA), work is **demand-driven** by law (Section 3).\n   - When monsoon fails or urban jobs collapse, millions of rural workers automatically register for 100 days of guaranteed wage work. Central expenditure automatically spikes, injecting purchasing power into rural distress without needing a new Act of Parliament!',
