        content: 'Fiscal Federalism: VFI = Centre collects ~60% taxes, States spend ~60% (Bridge = 41% tax devolution). HFI = Interstate capacity gap. Divisible Pool (Art 270) = Gross Central Taxes MINUS Cesses/Surcharges (Art 271) MINUS Collection costs. Central Sector Schemes = 100% Central funding (PM-KISAN). Centrally Sponsored Schemes (CSS) = Cost-shared (60:40 General States, 90:10 NE/Himalayan States; Core of Core = MGNREGA/NSAP).',
