        type: 'ARCHITECTURE_5M',
        content: 'Fiscal Federalism Transfer Matrix:\n1. Fiscal Imbalances:\n   - Vertical Fiscal Imbalance (VFI): $\\text{Revenue Share (Centre} \\approx 60\\%) \\ne \\text{Expenditure Share (States} \\approx 60\\%)$.\n   - Horizontal Fiscal Imbalance (HFI): Per-capita GSDP disparities across States ($> 4:1$ ratio).\n2. Divisible Pool Arithmetic (Article 270):\n   - $\\text{Net Divisible Pool} = \\text{Gross Tax Revenue (GTR)} - \\text{Cesses & Surcharges (Art 271)} - \\text{Cost of Collection}$.\n3. Central Programmatic Transfers Classification:\n   - Central Sector Schemes: $100\\%$ Central funding (Union List: Defence, Space, PM-KISAN, Fertilizers).\n   - Centrally Sponsored Schemes (CSS): Cost-shared ($60:40$ General, $90:10$ NE/Himalayan).\n     - Category I: Core of the Core (MGNREGA, NSAP - First charge on funds).\n     - Category II: Core Schemes (Jal Jeevan Mission, Samagra Shiksha, PMAY, PMGSY).\n     - Category III: Optional Schemes.',
